func recordBuiltinVerdictsTx(ctx context.Context, tx *writeTx, taskID int64, input ReviewVerdictInput) error {
	provider := ReviewProvider(builtinReviewProvider{})
	outcome := "clean"
	blocking := 0
	switch input.Verdict {
	case ReviewChangesRequested:
