		return false, err
	}
	defer rows.Close()
	for rows.Next() {
		var state, severity, origin string
		var inScope int
		if err := rows.Scan(&state, &severity, &origin, &inScope); err != nil {
			return false, err
		}
		if origin != "introduced" || inScope != 1 || !oneOf(state, "open", "fix_claimed", "unverified", "disputed", "regressed") {
